using System.ComponentModel;
using System.Net.Http.Json;
using System.Text.Json;
using Microsoft.Extensions.Logging;

namespace ResearchAgent.Tools;

/// <summary>
/// Provides web search capabilities using a search API.
/// </summary>
public sealed class WebSearchTool
{
    private readonly HttpClient _httpClient;
    private readonly ILogger<WebSearchTool> _logger;

    public WebSearchTool(HttpClient httpClient, ILogger<WebSearchTool> logger)
    {
        _httpClient = httpClient;
        _logger = logger;
    }

    [Description("Searches the web for information on a given query and returns relevant results with titles, snippets, and URLs.")]
    public async Task<string> SearchWebAsync(
        [Description("The search query to look up on the web")] string query,
        [Description("Maximum number of results to return (1-10)")] int maxResults = 5)
    {
        maxResults = Math.Clamp(maxResults, 1, 10);
        _logger.LogInformation("Searching web for: {Query} (max {MaxResults} results)", query, maxResults);

        try
        {
            // Use a public search API (DuckDuckGo Instant Answer API as a fallback-friendly option)
            var encodedQuery = Uri.EscapeDataString(query);
            var requestUri = $"https://api.duckduckgo.com/?q={encodedQuery}&format=json&no_html=1&skip_disambig=1";

            var response = await _httpClient.GetAsync(requestUri);
            response.EnsureSuccessStatusCode();

            var json = await response.Content.ReadFromJsonAsync<JsonElement>();
            var results = new List<SearchResult>();

            // Extract abstract if available
            var abstractText = json.GetProperty("Abstract").GetString();
            var abstractSource = json.GetProperty("AbstractSource").GetString();
            var abstractUrl = json.GetProperty("AbstractURL").GetString();

            if (!string.IsNullOrWhiteSpace(abstractText))
            {
                results.Add(new SearchResult(abstractSource ?? "Summary", abstractText, abstractUrl ?? ""));
            }

            // Extract related topics
            if (json.TryGetProperty("RelatedTopics", out var relatedTopics))
            {
                foreach (var topic in relatedTopics.EnumerateArray())
                {
                    if (results.Count >= maxResults) break;

                    var text = topic.TryGetProperty("Text", out var t) ? t.GetString() : null;
                    var firstUrl = topic.TryGetProperty("FirstURL", out var u) ? u.GetString() : null;

                    if (!string.IsNullOrWhiteSpace(text))
                    {
                        results.Add(new SearchResult("Related", text, firstUrl ?? ""));
                    }
                }
            }

            if (results.Count == 0)
            {
                return $"No results found for '{query}'. Try rephrasing the search query.";
            }

            var output = results.Select(r => $"[{r.Title}] {r.Snippet}\n  URL: {r.Url}");
            return string.Join("\n\n", output);
        }
        catch (HttpRequestException ex)
        {
            _logger.LogWarning(ex, "Web search failed for query: {Query}", query);
            return $"Search failed: {ex.Message}. Please try again with a different query.";
        }
    }

    private sealed record SearchResult(string Title, string Snippet, string Url);
}

using System.ComponentModel;
using Microsoft.Extensions.Logging;

namespace ResearchAgent.Tools;

/// <summary>
/// Provides note-taking capabilities for the research agent to organize findings.
/// </summary>
public sealed class NoteTakingTool
{
    private readonly List<ResearchNote> _notes = [];
    private readonly ILogger<NoteTakingTool> _logger;

    public NoteTakingTool(ILogger<NoteTakingTool> logger)
    {
        _logger = logger;
    }

    [Description("Saves a research note with a title and content. Use this to record important findings during research.")]
    public string SaveNote(
        [Description("A short descriptive title for the note")] string title,
        [Description("The content of the note — key facts, data, or insights")] string content)
    {
        var note = new ResearchNote(title, content, DateTime.UtcNow);
        _notes.Add(note);
        _logger.LogInformation("Note saved: {Title}", title);
        return $"Note #{_notes.Count} saved: '{title}'";
    }

    [Description("Retrieves all saved research notes to review findings so far.")]
    public string GetAllNotes()
    {
        if (_notes.Count == 0)
        {
            return "No notes have been saved yet.";
        }

        var formatted = _notes.Select((n, i) =>
            $"--- Note #{i + 1}: {n.Title} ---\n{n.Content}\n(Saved at {n.Timestamp:u})");

        return string.Join("\n\n", formatted);
    }

    [Description("Gets the total number of notes saved so far.")]
    public string GetNoteCount()
    {
        return $"Total notes saved: {_notes.Count}";
    }

    private sealed record ResearchNote(string Title, string Content, DateTime Timestamp);
}

