+using System.ComponentModel;
+using Microsoft.Extensions.Logging;
+
+namespace ResearchAgent.Tools;
+
+/// <summary>
+/// Provides note-taking capabilities for the research agent to organize findings.
+/// </summary>
+public sealed class NoteTakingTool
+{
+    private readonly List<ResearchNote> _notes = [];
+    private readonly ILogger<NoteTakingTool> _logger;
+
+    public NoteTakingTool(ILogger<NoteTakingTool> logger)
+    {
+        _logger = logger;
+    }
+
+    [Description("Saves a research note with a title and content. Use this to record important findings during research.")]
+    public string SaveNote(
+        [Description("A short descriptive title for the note")] string title,
+        [Description("The content of the note — key facts, data, or insights")] string content)
+    {
+        var note = new ResearchNote(title, content, DateTime.UtcNow);
+        _notes.Add(note);
+        _logger.LogInformation("Note saved: {Title}", title);
+        return $"Note #{_notes.Count} saved: '{title}'";
+    }
+
+    [Description("Retrieves all saved research notes to review findings so far.")]
+    public string GetAllNotes()
+    {
+        if (_notes.Count == 0)
+        {
+            return "No notes have been saved yet.";
+        }
+
+        var formatted = _notes.Select((n, i) =>
+            $"--- Note #{i + 1}: {n.Title} ---\n{n.Content}\n(Saved at {n.Timestamp:u})");
+
+        return string.Join("\n\n", formatted);
+    }
+
+    [Description("Gets the total number of notes saved so far.")]
+    public string GetNoteCount()
+    {
+        return $"Total notes saved: {_notes.Count}";
+    }
+
+    private sealed record ResearchNote(string Title, string Content, DateTime Timestamp);
+}
