 using Microsoft.Extensions.AI;
 using Microsoft.Extensions.Configuration;
 using Microsoft.Extensions.DependencyInjection;
 using Microsoft.Extensions.Logging;
 using Microsoft.Agents.AI;
 using OpenAI;
 using ResearchAgent.Tools;

 // Configuration
 var configuration = new ConfigurationBuilder()
     .AddEnvironmentVariables()
     .Build();

 var apiKey = configuration["OPENAI_API_KEY"]
     ?? throw new InvalidOperationException(
         "Set the OPENAI_API_KEY environment variable to run this application.");

 var modelId = configuration["OPENAI_MODEL"] ?? "gpt-4o-mini-2024-07-18";

 // DI setup
 var services = new ServiceCollection();

 services.AddLogging(builder => builder
     .AddConsole()
     .SetMinimumLevel(LogLevel.Information));

 services.AddSingleton<NoteTakingTool>();
 services.AddSingleton<HttpClient>();

 services.AddChatClient(
     new OpenAIClient(apiKey).GetChatClient(modelId).AsIChatClient());

 var provider = services.BuildServiceProvider();

 // Resolve dependencies
 var chatClient = provider.GetRequiredService<IChatClient>();
 var loggerFactory = provider.GetRequiredService<ILoggerFactory>();
 var httpClient = provider.GetRequiredService<HttpClient>();
 var webSearchTool = new WebSearchTool(httpClient, loggerFactory.CreateLogger<WebSearchTool>());
 var noteTakingTool = provider.GetRequiredService<NoteTakingTool>();
 var logger = provider.GetRequiredService<ILogger<Program>>();

 // Define tools available to the agent
 var tools = new AITool[]
 {
     AIFunctionFactory.Create(webSearchTool.SearchWebAsync),
     AIFunctionFactory.Create(noteTakingTool.SaveNote),
     AIFunctionFactory.Create(noteTakingTool.GetAllNotes),
     AIFunctionFactory.Create(noteTakingTool.GetNoteCount),
 };

 // Create the research agent using Microsoft Agent Framework
 var agent = new ChatClientAgent(
     chatClient,
     name: "ResearchAgent",
     description: "An AI research assistant that searches the web and takes notes to summarize findings.",
     instructions: """
         You are a research agent. Your job is to research a topic thoroughly by:
         1. Searching the web for relevant information using the SearchWebAsync tool.
         2. Saving important findings as notes using the SaveNote tool.
         3. Performing multiple searches to cover different aspects of the topic.
         4. After gathering enough information, reviewing all your notes with GetAllNotes.
         5. Providing a comprehensive summary of your findings.

         Always save key facts as notes before summarizing. Aim for at least 3 searches
         on different aspects of the topic to ensure breadth of coverage.
         """,
     tools: tools);

 // Get the research topic
 Console.WriteLine("╔══════════════════════════════════════════╗");
 Console.WriteLine("║       AI Research Agent                   ║");
 Console.WriteLine("╚══════════════════════════════════════════╝");
 Console.WriteLine();

 string topic;
 if (args.Length > 0)
 {
     topic = string.Join(' ', args);
 }
 else
 {
     Console.Write("Enter a research topic: ");
     topic = Console.ReadLine() ?? "artificial intelligence";
 }

 Console.WriteLine($"\nResearching: {topic}\n");

 // Run the agent
 var runOptions = new ChatClientAgentRunOptions(new ChatOptions
 {
     Temperature = 0f,
     MaxOutputTokens = 2048,
 });

 try
 {
     var session = await agent.CreateSessionAsync();
     var userMessage = $"Research the following topic and provide a comprehensive summary: {topic}";

     await foreach (var message in agent.RunStreamingAsync(userMessage, session, runOptions))
     {
         if (message.Role == ChatRole.Assistant && message.Text is { Length: > 0 } text)
         {
             Console.Write(text);
         }
     }

     Console.WriteLine("\n\n--- Research Complete ---");
 }
 catch (Exception ex)
 {
     logger.LogError(ex, "Research agent encountered an error");
     Console.WriteLine($"\nError: {ex.Message}");
 }

